// Set Lucide (ISC, ver assets/icons/LICENSE-lucide.txt): SVG propios bundleados
// y embebidos por Vite (sin requests extra). Se usa con el prefijo `lucide:`.
const LUCIDE_RAW = import.meta.glob('../assets/icons/lucide/*.svg', {
  eager: true,
  query: '?raw',
  import: 'default'
})

const LUCIDE = Object.fromEntries(
  Object.entries(LUCIDE_RAW).map(([path, raw]) => [
    path.slice(path.lastIndexOf('/') + 1, -'.svg'.length),
    String(raw)
      .replace(/^[\s\S]*?<svg[^>]*>/i, '')
      .replace(/<\/svg>[\s\S]*$/i, '')
  ])
)

const isLucide = computed(() => props.name.startsWith('lucide:'))
const isBrand = computed(() => !isLucide.value && props.name in BRAND_ICONS)
const html = computed(() => {
  if (isLucide.value) {
    const key = props.name.slice('lucide:'.length)
    return LUCIDE[key] || LUCIDE.sparkles || ICONS.sparkles || ''
  }
  return ICONS[props.name] || BRAND_ICONS[props.name] || ''
})
</script>

<template>
  <svg
    class="icon"
    :width="size"
    :height="size"
    viewBox="0 0 24 24"
    :fill="isBrand ? 'currentColor' : 'none'"
    :stroke="isBrand ? 'none' : 'currentColor'"
    :stroke-width="stroke"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
    focusable="false"
    v-html="html"
  />
</template>
